import {defaults} from './motion.js';
const shot=(options={})=>({...defaults(),walk:false,...options});
export const lessons=[
 {id:'scale',title:'01 · 풍경에서 인물로',goal:'시작에는 여행지 공간을 넓게 보여주고, 끝에는 인물의 존재감을 키우세요. 인물 전체가 프레임 안에 남도록 설계하세요.',tip:'화각을 좁히는 것과 카메라가 접근하는 것은 다릅니다. 먼저 24mm로 거리 차이를 만들고 시작·끝을 비교하세요.',initial:shot(),example:shot({start:{x:0,y:1.6,z:12},end:{x:0,y:1.6,z:4.2},focal:35}),why:'Dolly로 인물 크기를 키우면서 전경과 배경의 상대 위치도 바뀝니다. 중앙 배치도 인물 강조라는 목적에 맞는 선택입니다.'},
 {id:'lead',title:'02 · 진행 방향에 여백 주기',goal:'왼쪽에서 오른쪽으로 걷는 인물을 촬영합니다. 인물 오른쪽에 진행할 공간을 남기고, 이동 중에도 전신이 잘리지 않게 하세요.',tip:'피사체 추적을 켠 뒤 「프레임 좌우 배치」를 왼쪽으로 움직여 보세요. 삼분할은 출발점이지 의무가 아닙니다.',initial:shot({walk:true,start:{x:0,y:1.6,z:6},end:{x:1,y:1.6,z:6},focal:35}),example:shot({walk:true,start:{x:-1,y:1.6,z:6},end:{x:1,y:1.6,z:6},focal:35,frameX:-.35}),why:'인물을 왼쪽에 두어 오른쪽 진행 방향에 공간을 남깁니다. 이동 방향이 달라지면 여백을 둘 쪽도 바뀝니다.'},
 {id:'depth',title:'03 · 전경으로 깊이감 만들기',goal:'인물보다 가까운 바위나 나무를 프레임에 넣고 옆으로 이동해 전경과 배경이 다르게 움직이는 모습을 만드세요. 인물이 계속 가려지면 안 됩니다.',tip:'촬영장에서 바위 가까이에 카메라를 두고 시작·끝 X를 다르게 설정하세요. 전경이 얼굴을 가리는지도 확인하세요.',initial:shot({start:{x:-2,y:1.6,z:10},end:{x:-2,y:1.6,z:8}}),example:shot({start:{x:-5,y:1.6,z:10},end:{x:0,y:1.6,z:10},focal:24}),why:'가까운 왼쪽 바위를 포함한 채 옆으로 이동하면 전경의 화면 이동이 먼 배경보다 커집니다. 이 예시는 여러 가능한 경로 중 하나입니다.'},
 {id:'low',title:'04 · 낮은 시점으로 공간 강조',goal:'카메라를 허리 아래로 낮추고, 인물 전체와 주변 공간을 함께 보여주세요. 인물 얼굴이 바위·나무·건물에 가리지 않도록 하세요.',tip:'높이를 0.3~0.8m에서 시험하고 화각과 바라보는 높이를 조절하세요. 낮은 시점이 항상 더 좋은 구도라는 뜻은 아닙니다.',initial:shot({start:{x:0,y:1.6,z:6},end:{x:0,y:1.6,z:5},focal:35}),example:shot({start:{x:0,y:.5,z:6},end:{x:0,y:.5,z:5},focal:24,aimY:1.1}),why:'낮은 위치에서 인물을 올려다보면 하늘과 몸의 윤곽을 함께 보여주기 쉽습니다. 넓은 화각으로 환경을 유지합니다.'},
 {id:'finish',title:'05 · 이동 끝에서 인물 강조',goal:'Dolly나 Orbit으로 인물에 시선을 모으세요. 종료 구도에서 인물 크기를 확보하고, 경로 전체에서 머리·몸이 프레임을 벗어나지 않도록 하세요.',tip:'좋은 마지막 프레임만으로 충분하지 않습니다. 타임라인을 움직여 중간에 가림이나 프레임 이탈이 생기는지 확인하세요.',initial:shot({mode:'orbit',start:{x:-7,y:1.6,z:7},arc:100}),example:shot({mode:'orbit',start:{x:-3,y:1.6,z:4},end:{x:0,y:1.6,z:5},arc:65,focal:35}),why:'반경 5m의 짧은 Orbit으로 인물의 크기를 유지하며 배경을 바꿉니다. 안전한 Dolly 접근도 목표를 달성할 수 있습니다.'}
];
export function judge(id,samples,meta,criteria={}){
 const a=samples[0],b=samples.at(-1),inside=samples.filter(s=>s.inside).length/samples.length,clear=samples.filter(s=>!s.occluded).length/samples.length;
 const checks=[{name:'이동 중 전신 프레임 유지',ok:id==='reveal'?samples.slice(-9).every(s=>s.inside):inside>=.9,evidence:`${samples.filter(s=>s.inside).length}/${samples.length} 시점에서 전신 경계가 화면 안에 있습니다.`,advice:'거리·화각·바라보는 높이를 조절하고 중간 프레임을 확인하세요.'},{name:'머리·몸통 가림 피하기',ok:id==='reveal'?samples.slice(-9).every(s=>!s.occluded):clear>=.9,evidence:`${samples.filter(s=>s.occluded).length}/${samples.length} 시점에서 머리 또는 몸통으로 향하는 시선이 환경 물체에 가립니다.`,advice:'카메라 경로를 옆으로 옮기거나 높이를 바꿔 가림을 줄여 보세요.'}];
 const add=(name,ok,evidence,advice)=>checks.push({name,ok,evidence,advice});
 if(id==='scale'){add('시작의 넓은 공간',a.height>=.04&&a.height<=.3,`시작 인물 높이 ${(a.height*100).toFixed(0)}%`,'시작 거리를 늘리거나 초점거리를 줄여 공간을 보여주세요.');add('끝에서 인물 강조',b.height>=(criteria.endMin??.35)&&b.height<=.85&&b.height/Math.max(a.height,.001)>=1.4,`종료 높이 ${(b.height*100).toFixed(0)}% · 크기 변화 ${(b.height/Math.max(a.height,.001)).toFixed(1)}배`,'종료점을 가까이 두되 머리와 발이 잘리지 않는지 확인하세요.');}
 if(id==='lead'){const lead=samples.filter(s=>s.motionRight?(s.centerX>=.18&&s.centerX<=.46&&s.rightSpace>s.leftSpace+.08):(s.centerX>=.54&&s.centerX<=.82&&s.leftSpace>s.rightSpace+.08)).length/samples.length;add('진행 방향 앞쪽 여백',lead>=.8,`${Math.round(lead*100)}% 시점에서 진행 방향 앞쪽 여백을 확보했습니다.`,'추적을 켜고 좌우 배치를 진행 방향의 반대쪽으로 옮겨 보세요.');add('걷는 동선 사용',meta.walk,'현재 문제의 걷는 동선을 검사합니다.','인물 걷기를 켜세요.');}
 if(id==='depth'){const visible=samples.some(s=>s.foreground.length>0);let parallax=0;for(const f of a.foreground){const match=b.foreground.find(x=>x.id===f.id);if(match)parallax=Math.max(parallax,Math.abs((match.x-b.backgroundX)-(f.x-a.backgroundX)));}add('전경 포함',visible,'인물보다 가까운 환경 물체의 화면 투영을 확인합니다.','바위나 나무를 프레임 가장자리에 넣어 보세요.');add('전경과 배경의 상대 이동',visible&&parallax>=.05,`공통 전경의 배경 대비 상대 이동 ${(parallax*100).toFixed(1)}%p`,'시작·끝의 좌우 위치를 바꾸고 같은 전경이 두 프레임에 남는지 확인하세요.');}
 if(id==='low'){add('낮은 카메라 시점',meta.maxHeight<=(criteria.maxHeight??.8),`경로의 최고 높이 ${meta.maxHeight.toFixed(1)}m`,'시작점과 종료점 높이를 모두 0.8m 이하로 낮춰 보세요.');add('인물과 공간의 균형',b.height>=.15&&b.height<=.65,`종료 인물 높이 ${(b.height*100).toFixed(0)}%`,'전신과 주변 공간이 함께 보이도록 거리나 화각을 조절하세요.');}
 if(id==='finish'){add('종료 인물 크기',b.height>=(criteria.endMin??.35)&&b.height<=.85,`종료 인물 높이 ${(b.height*100).toFixed(0)}%`,'거리와 화각으로 마지막 인물 크기를 확보하세요.');add('실제 카메라 이동',meta.length>=1,`이동 거리 ${meta.length.toFixed(1)}m`,'시작·끝 위치 또는 Orbit 회전각으로 1m 이상 이동해 보세요.');}
 if(id==='reveal'){add('시작 가림',a.occluded,'시작 시 머리·몸통을 향하는 광선이 전경에 가리는지 검사합니다.','시작점을 바위와 인물이 겹치는 위치로 옮겨 보세요.');add('마지막 20%에서 드러남',samples.slice(-9).every(s=>!s.occluded&&s.inside),'종료에 가까운 9개 시점에서 가림과 프레임 이탈을 확인합니다.','종료 경로를 바위 옆으로 빼서 시야를 확보하세요.');}
 if(id==='horizon'){for(const [label,s] of [['시작',a],['종료',b]])add(label+' 수평선 위치',s.horizon>=criteria.horizonMin&&s.horizon<=criteria.horizonMax,label+' 수평선: 화면 위에서 '+(s.horizon*100).toFixed(0)+'%','바라보는 높이 또는 수동 상하 방향을 조절하세요.');}
 if(id==='orbit'){add('Orbit 회전',meta.mode==='orbit'&&Math.abs(meta.arc)>=criteria.minArc,'현재 '+meta.mode+' · '+Math.abs(meta.arc).toFixed(0)+'°','Orbit 모드를 선택하고 회전각을 확보하세요.');add('크기 유지',Math.abs(b.height/Math.max(a.height,.001)-1)<=.2&&b.height>=.3&&b.height<=.85,'시작→끝 크기 변화 '+((b.height/a.height-1)*100).toFixed(1)+'%','반경과 초점거리를 조절해 인물 크기를 유지하세요.');}
 return{checks,score:Math.round(checks.filter(c=>c.ok).length/checks.length*100),inside,clear,start:a,end:b,worst:samples.reduce((worst,s)=>s.penalty>worst.penalty?s:worst,samples[0])};
}
